import { StyleSheet } from "@/lib/pdf-primitives";
import type { PdfcnTheme } from "@/types/pdf-themes";

/**
 * Creates all timeline styles derived from the active theme.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createTimelineStyles = (t: PdfcnTheme) => {
  const { spacing, fontWeights, typography } = t.primitives;

  return StyleSheet.create({
    body: {
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.sm,
      lineHeight: t.typography.body.lineHeight,
      marginTop: spacing[1],
    },
    container: {
      display: "flex",
      flexDirection: "column",
      marginBottom: t.spacing.componentGap,
      width: "100%",
    },
    content: {
      flex: 1,
      paddingBottom: spacing[4],
      paddingLeft: spacing[3],
    },
    contentLast: {
      paddingBottom: 0,
    },
    date: {
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.sm,
      lineHeight: t.typography.body.lineHeight,
      width: 80,
    },
    dot: {
      borderRadius: 4,
      height: 8,
      width: 8,
    },
    rail: {
      alignItems: "center",
      alignSelf: "stretch",
      paddingTop: spacing[1],
      width: spacing[4],
    },
    row: {
      alignItems: "flex-start",
      flexDirection: "row",
    },
    spine: {
      flex: 1,
      marginTop: spacing[1],
      width: 2,
    },
    title: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.semibold,
      lineHeight: t.typography.body.lineHeight,
    },
  });
};

import type React from "react";

import {
  usePdfcnTheme,
  useSafeMemo,
} from "@/components/pdf/theme-provider";
import {
  View,
  Text as PDFText,
} from "@/lib/pdf-primitives";
import type { Style } from "@/lib/pdf-primitives";
import { resolveColor } from "@/lib/resolve-color";

import { createTimelineStyles } from "./timeline.styles";
import type { TimelineItem, TimelineProps } from "./timeline.types";

type Styles = ReturnType<typeof createTimelineStyles>;

const renderItem = (
  item: TimelineItem,
  index: number,
  total: number,
  accent: string,
  styles: Styles
): React.ReactElement => {
  const isLast = index === total - 1;
  return (
    <View key={index} wrap={false} style={styles.row}>
      <PDFText style={styles.date}>{item.date}</PDFText>
      <View style={styles.rail}>
        <View style={[styles.dot, { backgroundColor: accent }]} />
        {isLast ? null : (
          <View style={[styles.spine, { backgroundColor: accent }]} />
        )}
      </View>
      <View style={[styles.content, isLast ? styles.contentLast : {}]}>
        <PDFText style={styles.title}>{item.title}</PDFText>
        {item.body ? <PDFText style={styles.body}>{item.body}</PDFText> : null}
      </View>
    </View>
  );
};

export const Timeline = ({
  items,
  accentColor = "primary",
  style,
  noWrap = false,
}: TimelineProps) => {
  const theme = usePdfcnTheme();
  const styles = useSafeMemo(() => createTimelineStyles(theme), [theme]);
  const accent = resolveColor(accentColor, theme.colors);

  const containerStyles: Style[] = [styles.container];
  if (style) {
    containerStyles.push(...[style].flat());
  }

  return (
    <View wrap={!noWrap} style={containerStyles}>
      {items.map((item, index) =>
        renderItem(item, index, items.length, accent, styles)
      )}
    </View>
  );
};

import type { Style } from "@/lib/pdf-primitives";

/**
 * A single dated milestone on the timeline.
 * Props - `date` | `title` | `body`
 * @see {@link TimelineItem}
 */
export interface TimelineItem {
  date: string;
  title: string;
  body?: string;
}

/**
 * Vertical timeline of dated milestones with an accent spine and dot markers.
 * Props - `items` | `accentColor` | `style` | `noWrap`
 * @see {@link TimelineProps}
 */
export interface TimelineProps {
  items: TimelineItem[];
  /**
   * Theme color token or CSS color applied to the spine and dot markers.
   * @default 'primary'
   */
  accentColor?: string;
  style?: Style;
  /**
   * @default false
   */
  noWrap?: boolean;
}
